"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5086],{9345(e){e.exports=JSON.parse('{"title":"\uc0ac\ub78c\uc744 \uc704\ud55c \ucf54\ub4dc\ub294 \ub9e4\uc6b0 \uc5b4\ub835\ub2e4","date":"2024-10-11","coverUrl":null,"html":"<h2 data-notion-block-id=\\"fbc05ccb-c6c6-485a-af14-5ba5f0e92580\\" id=\\"fbc05ccb-c6c6-485a-af14-5ba5f0e92580\\">\uc0ac\ub78c\uc744 \uc704\ud55c \ucf54\ub4dc\ub294 \ub9e4\uc6b0 \uc5b4\ub835\ub2e4</h2><a href=\\"https://erikbern.com/2024/09/27/its-hard-to-write-code-for-humans\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://erikbern.com/2024/09/27/its-hard-to-write-code-for-humans</a><p data-notion-block-id=\\"3757b75b-628f-4481-a0cf-0dbb57d1b68a\\"><b>\uc2ec\uc724\uc12d</b>: \ucef4\ud4e8\ud130\ub97c \uc704\ud574 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\uace0, \ucd5c\uc801\ud654\ud558\ub294 \uac83\uc740 \uc27d\uc9c0\ub9cc, \uc0ac\ub78c\uc744 \uc704\ud574 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\uace0 \uc0ac\ub78c\uc774 \uc778\uc2dd\ud558\uae30 \uc27d\uac8c \ucd5c\uc801\ud654\ud558\ub294 \uac83\uc740 \uc27d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc744 \uc704\ud574, \uc608\uc2dc \uc911\uc2dc, \uac04\ub2e8\ud55c \uac1c\ub150 \uc911\uc2dc, \ucee4\uc2a4\ud140 \uac00\ub2a5\uc744 \ub9c9\uc9c0 \ub9d0\uae30\u2026 \uc5ec\ub7ec\uac00\uc9c0\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c, \ubaa8\ub4e0 \uc81c\ud488\uc5d0 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc0ac\uc6a9\uc790\ub97c \uc704\ud574 \ucf54\ub4dc\uc640 \ubb38\uc11c\ub97c \uc791\uc131\ud558\ub294 \uac83\uc5d0 \ub300\ud574 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ub9cc\ub4dc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc800\uc790\uac00 \uc608\uc2dc\uac00 \uc911\uc694\ud558\ub2e4\uace0 \ud588\uc9c0\ub9cc, \uadf8\uc5d0 \ubabb\uc9c0 \uc54a\uac8c \ud575\uc2ec \uac1c\ub150\uacfc \ub514\uc790\uc778 \uc6d0\uce59\uc744 \uc124\uba85\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud558\uba70, \uac1c\ub150\uc744 \uc801\uac8c \uc720\uc9c0\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc, \ubcf4\ud3b8\uc801\uc774\uc9c0 \uc54a\uc740 \uac1c\ub150\ub4e4\uc774 \ud544\uc694\ud560\uc9c0\ub3c4 \ubaa8\ub985\ub2c8\ub2e4. \uc5b8\uc81c\ub098 \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc911\uc2ec\uc744 \ucc3e\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \uc77c\uae68\uc6cc\uc8fc\ub294 \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"b041af54-de92-4d34-b58c-e8e3a31bcfe5\\"><b>\uae40\ub300\uad00</b>: \ucef4\ud4e8\ud130\ub97c \uc704\ud55c \ucf54\ub4dc\ub294 \ucef4\ud4e8\ud130\uac00 \uc77c\uad00\ub41c \ub17c\ub9ac\uc640 \uaddc\uce59\uc5d0 \ub530\ub77c \uc791\ub3d9\ud558\uae30 \ub54c\ubb38\uc5d0 \ucd5c\uc801\ud654\ud558\uae30 \uc0c1\ub300\uc801\uc73c\ub85c \uc27d\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ub78c\ub9c8\ub2e4 \uac1c\uc131\uacfc \ubc30\uacbd \uc9c0\uc2dd, \uc0ac\uace0\ubc29\uc2dd\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0, \uc0ac\ub78c\ub4e4\uc774 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub294 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\ub294 \uac83\uc740 \ud6e8\uc52c \ub354 \uc5b4\ub824\uc6b4 \uc77c\uc785\ub2c8\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ud611\uc5c5\uc744 \uc704\ud574\uc11c\ub294, \uc11c\ub85c\uac00 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub294 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\uba70, \uc774\ub294 \ud68c\uc0ac \ub0b4 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub098 \ubb38\uc11c \uc791\uc131 \ubc29\uc2dd\uc5d0 \ub9de\ucd94\uc5b4 \uc720\uc9c0\ubcf4\uc218 \uac00\ub2a5\ud55c \ucf54\ub4dc\ub97c \uc791\uc131\ud558\ub294 \ub2a5\ub825\uc73c\ub85c\ub3c4 \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uacb0\uad6d, \ud611\uc5c5 \ud658\uacbd\uc5d0\uc11c\ub294 \uc0c1\ud638 \uc874\uc911\uacfc \uc9c0\uc2dd \ucc28\uc774\ub97c \uc904\uc774\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"43fd3b42-d45a-41a4-9c06-7c964fdfe958\\" id=\\"43fd3b42-d45a-41a4-9c06-7c964fdfe958\\">\ubc88\ub4e4\ub7ec\uc758 \uc5ed\uc0ac</h2><a href=\\"https://www.youtube.com/watch?v=JUS6EPMbk0U\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=JUS6EPMbk0U</a><p data-notion-block-id=\\"df5cf54d-aa88-4cac-a8c4-404c48b75eca\\"><b>\uc2ec\uc724\uc12d</b>: React Spectrum\ud300\uc758 \ud14c\ud06c\ub9ac\ub4dc\uac00 Parcel\uacfc LightningCSS\ub97c \uac1c\ubc1c\ud55c \uacbd\ud5d8\uc744 \uae30\ubc18\uc73c\ub85c  \ubc88\ub4e4\ub7ec\uc758 \uc5ed\uc0ac\ub97c \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uc5ed\uc0ac\ub97c \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, CJS\uc640 AMD, ESM\uc5d0 \ub300\ud55c \uac1c\ub150, \ubc88\ub4e4\ub7ec\uc758 \uac04\ub2e8\ud55c \uc5ed\uc0ac\uc640 \uad6c\uc870, \uadf8\ub9ac\uace0 \ubc88\ub4e4\ub7ec\uc758 \ubbf8\ub798\ub97c \uc124\uba85\ud558\ub2c8, \uc790\ub9c9\uacfc \ud568\uaed8 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 Rolldown\uc758 \uadfc\ud669(<a href=\\"https://voidzero.dev/posts/announcing-voidzero-inc\\">VoidZero \ud68c\uc0ac \uc124\ub9bd</a>), Tree shaking \ub525\ub2e4\uc774\ube0c\ub97c \uc6d0\ud55c\ub2e4\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/e118a44c46de44b79492998633298d32#a0608cf9-07a8-4413-95e5-f535e3811bff\\">Tree shaking\uc774 \ubb54\ub370?</a>\ub97c, \ub2e4\ub978 \ubc88\ub4e4\ub7ec\uc758 \uad6c\uc870\uac00 \uad81\uae08\ud558\ub2e4\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#b3476a56-0b24-42a0-b655-abe1c6283f73\\">Vite\ub294 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub098\uc694?</a>\uc601\uc0c1\uc5d0\uc11c Vite\uc758 \uad6c\uc870\ub97c \ud655\uc778\ud574\ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"8409d00f-1b8d-45bb-a477-6db3b48fcb94\\" id=\\"8409d00f-1b8d-45bb-a477-6db3b48fcb94\\">\ud504\ub860\ud2b8\uc5d4\ub4dc \ud14c\uc2a4\ud2b8 \ubc29\ud5a5\uc131 \ucc3e\uae30</h2><a href=\\"https://www.meticulous.ai/blog/lessons-from-a-decade\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.meticulous.ai/blog/lessons-from-a-decade</a><p data-notion-block-id=\\"c3f8db6a-9d1a-41e8-9f43-6f173c04e9af\\">\uc81c\ud488 \ud64d\ubcf4 \uae00\uc774\uc9c0\ub9cc, \ub2e8\uc704 \ud14c\uc2a4\ud2b8\ub97c \uc5b4\ub5bb\uac8c \ubd84\ub9ac\ud560\uc9c0, \ucef4\ud3ec\ub10c\ud2b8 \ud14c\uc2a4\ud2b8\uc640 \ud1b5\ud569 \ud14c\uc2a4\ud2b8\ub294 \uc5b4\ub5bb\uac8c \uc811\uadfc\ud560\uc9c0\uc5d0 \ub300\ud574 \uc801\uc740 \ud765\ubbf8\ub85c\uc6b4 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \ud14c\uc2a4\ud2b8\uc5d0 \uc801\uc6a9\ub418\ub294 \uae00\uc740 \uc544\ub2c8\uaca0\uc9c0\ub9cc, \ud55c \ubc88 \uc811\uadfc \ubc29\uc2dd\uc744 \uc791\uc131\ud560 \ub54c \uc801\uc6a9\ud574\ubd10\ub3c4 \uad1c\ucc2e\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"e6b4c895-1639-4fc6-9615-165f3a47cd82\\" id=\\"e6b4c895-1639-4fc6-9615-165f3a47cd82\\">Web Component \uc774\ub300\ub85c \uac00\uba74(\ub77c\uc774\ub354)</h2><a href=\\"https://dev.to/ryansolid/web-components-are-not-the-future-48bh\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/ryansolid/web-components-are-not-the-future-48bh</a><a href=\\"https://www.abeautifulsite.net/posts/web-components-are-not-the-future-they-re-the-present/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.abeautifulsite.net/posts/web-components-are-not-the-future-they-re-the-present/</a><a href=\\"https://nolanlawson.com/2024/09/28/web-components-are-okay/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nolanlawson.com/2024/09/28/web-components-are-okay/</a><p data-notion-block-id=\\"3b56c4ad-26ed-40ca-a07f-210debddf025\\"><b>\uc2ec\uc724\uc12d</b>: Web Component\uc5d0 \uad00\ud55c \uad00\uc810\uc744 \ub2e4\ub8ec \uc138\uac00\uc9c0 \uae00\uc785\ub2c8\ub2e4. \uccab \uae00\uc740 Web Component\uc758 \ubaa8\ub358 JS \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \ube44\ud574 \ubd80\uc871\ud55c \uc810\uc744 \uc5ec\ub7ff \uc774\uc57c\uae30\ud558\uba70, \uc6f9 \ud45c\uc900\uc73c\ub85c \ub108\ubb34 \ubd80\uc871\ud558\uba70, \uc0ac\uc6a9\ud558\ub294\ub370 \uae30\ud68c\ube44\uc6a9\uc774 \ub108\ubb34 \ud06c\ub2e4\ub294 \uc8fc\uc7a5\uc744 \ud569\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 \uccab \uae00\uc774 \ud504\ub808\uc784\uc6cc\ud06c \uac1c\ubc1c\uc790\uc758 \uc785\uc7a5\uc774 \ub108\ubb34 \ub4e4\uc5b4\uac00 \uc788\uc74c\uc744 \uc9c0\uc801\ud558\uba70, Web Component\uac00 \ucda9\ubd84\ud788 \ubc1c\uc804\ud558\uace0 \uc788\uc73c\uba70, \uc5ec\ub7ec \uc7a5\uc810\uc774 \uc788\ub2e4\uace0 \uc8fc\uc7a5\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc138\ubc88\uc9f8 \uae00\uc740 Web Component\uac00 \ud45c\uc900\uc744 \uc815\ud558\uace0 \ud558\uc704 \ud638\ud658\uc131\uc744 \ubcf4\uc7a5\ud558\ub294 \uce21\uba74\uc5d0\uc11c \uc88b\uc9c0\ub9cc, \uc131\ub2a5\uacfc \ub2e4\ub978 JS \ud504\ub808\uc784\uc6cc\ud06c\uc640 \ud638\ud658\uc131\uc5d0\uc11c \ubd88\ud3b8\ud568\uc744 \ub290\ub084 \uc218 \uc788\ub2e4\ub294 \uc911\ub9bd\uc801\uc778 \uc785\uc7a5\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. Web Component\uc5d0 \uad00\ud55c \uad00\uc810\uc740 \ub9e4\uc6b0 \ub2e4\uc591\ud558\uace0, \uc5ec\ub7ec\uac00\uc9c0\ub97c \uc18c\uac1c\ud588\uc2b5\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4dabcc7-9269-46bc-a2f2-ed10f9fcf35f#be73799f-a514-4f83-a14e-c0ec0cdd2dfe\\">Web Component\ub294 \uae30\uc874 \ud504\ub808\uc784\uc6cc\ud06c\uc640 \uc0c1\ud638\ubcf4\uc644\uc801\uc774\ub2e4.</a>\uc5d0\uc11c \uc5ec\ub7ec\uac00\uc9c0 \uc785\uc7a5\uc744 \uc18c\uac1c\ud588\uc9c0\ub9cc, \ud45c\uc900\uc774 JS \ud2b8\ub80c\ub4dc\uc5d0 \ube44\ud574 \ub9ce\uc774 \ubc1c\uc804\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810, \uae30\uc874 JS \ud504\ub808\uc784\uc6cc\ud06c \uae30\ubc18 \uac1c\ubc1c\uc790\uac00 \uc811\uadfc\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \uc88b\uc9c0 \uc54a\uc9c0\ub9cc, <a href=\\"https://nolanlawson.com/2023/08/23/use-web-components-for-what-theyre-good-at/\\">\uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\ub294 \uacf3\uc5d0\ub294 \uc0ac\uc6a9\ud558\uae30 \uc88b\ub2e4\ub294 \uc810</a>\uc5d0\uc11c \uc8fc\ubaa9\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"0f883ef1-01c7-4e1e-9a80-2678b359a4b0\\" id=\\"0f883ef1-01c7-4e1e-9a80-2678b359a4b0\\">\ud14c\uc2a4\ud2b8\uc5d0\uc11c \uc544\ub2d8\uc744 \uc8fc\uc7a5\ud558\uae30</h2><a href=\\"https://www.epicweb.dev/inverse-assertions\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicweb.dev/inverse-assertions</a><p data-notion-block-id=\\"f41b0b56-2185-46de-9f49-cafe4856aef9\\"><code>Jest</code>\ub098 <code>Vitest</code>\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \ub2e8\uc5b8\uc5d0\uc11c, \uc5c6\ub2e4\ub294 \uac83\uc774\ub098 \uc544\ub2d8\uc744 \uc8fc\uc7a5\ud558\uae30 \uc704\ud574\uc11c <code>waitFor</code>\uacfc <code>expect</code>\ud568\uc218\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"28668781-1e4f-4bee-8c9d-d169056ef5eb\\" id=\\"28668781-1e4f-4bee-8c9d-d169056ef5eb\\">CSS for A11y</h2><a href=\\"https://www.youtube.com/watch?v=ob_M_qXeDVE\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=ob_M_qXeDVE</a><p data-notion-block-id=\\"4ed61caf-db91-4d3b-a32c-b9636c027a8c\\"><b>\uc2ec\uc724\uc12d</b>: \uc811\uadfc\uc131\uc740 HTML\uacfc JS\uc5d0\ub9cc \ud574\ub2f9\ub418\ub294 \uac83\uc774 \uc544\ub2cc, CSS \uc18d\uc131\uc5d0\ub3c4 \ud574\ub2f9\ub418\uba70, \uc5b4\ub5a4 \uc18d\uc131\ub4e4\uc774 \ud574\ub2f9\ub418\ub294\uc9c0, \uc811\uadfc\uc131\uc744 \ubcf4\uc7a5\ud558\ub294 \ubaa8\ubc94 \uc0ac\ub840\ub97c \uc124\uba85\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub294 \ubc1c\ud45c\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uc811\uadfc\uc131\uc744 \uace0\ub824\ud560 \ub54c CSS\uc758 \uc5b4\ub5a4 \ubd80\ubd84\ub3c4 \uace0\ub824\ud574\uc57c \ud558\ub294\uc9c0 \uc0c1\uae30\uc2dc\ud0a4\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"61bc91cd-6e69-42cc-89dc-39c7a3f4a2a3\\" id=\\"61bc91cd-6e69-42cc-89dc-39c7a3f4a2a3\\">Duration Function \uac1c\ub150 \uc18c\uac1c</h2><a href=\\"https://www.inngest.com/blog/durable-functions-a-visual-javascript-primer\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.inngest.com/blog/durable-functions-a-visual-javascript-primer</a><p data-notion-block-id=\\"21e79291-779e-4b7e-b716-30dd152bcd33\\">\uc6cc\ud06c\ud50c\ub85c\uc6b0(ex, cron, \uc774\uba54\uc77c\u2026)\ub97c \uc2e4\ud589\uc744 \ubcf4\uc7a5\ud558\ub294 \ub2a5\ub825\uc744 \ub73b\ud558\ub294 Duration Function\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\ub85d \uc81c\ud488 \ud64d\ubcf4\uac00 \ub4e4\uc5b4\uac00 \uc788\uc9c0\ub9cc, \ud0a4\uc6cc\ub4dc\uc640 \uc5b4\ub5bb\uac8c \uc2e4\ud589\ub418\ub294\uc9c0\ub97c \uc0b4\ud53c\ub294 \uc6a9\ub3c4\ub85c \ub098\uc058\uc9c0 \uc54a\uc740 \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"5bccdfa5-5519-4a47-85b6-15e55ddef4bc\\" id=\\"5bccdfa5-5519-4a47-85b6-15e55ddef4bc\\">\ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d JS\ub85c \uc785\ubb38\ud558\uae30</h2><a href=\\"https://janhesters.com/blog/unleash-javascripts-potential-with-functional-programming\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://janhesters.com/blog/unleash-javascripts-potential-with-functional-programming</a><p data-notion-block-id=\\"41c9dd1c-66a0-4369-b972-a9d5e954d7e4\\">\ud56d\uc0c1 \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \uc0ac\uc6a9\ud558\uae30\uc5d4 \ubb34\ub9ac\uac00 \uc788\uaca0\uc9c0\ub9cc, JS\uc758 \uc5b4\ub290 \ubd80\ubd84\uc774 \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d \uac1c\ub150\uc774 \ub4e4\uc5b4\uac14\ub294\uc9c0, \uc5b4\ub5a4 \uac1c\ub150\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud558\uae30\uc5d0 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"caf1f660-0b22-4ea0-b299-ec5ccd1ea0a8\\" id=\\"caf1f660-0b22-4ea0-b299-ec5ccd1ea0a8\\">\uc0c8\ub85c\uc6b4 \uac83\ub4e4</h2><a href=\\"https://bloomberg.github.io/stricli/blog/intro/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bloomberg.github.io/stricli/blog/intro/</a><a href=\\"https://github.com/microsoft/code-push-server\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/microsoft/code-push-server</a><a href=\\"https://dmno.dev/blog/dmno-nextjs-launch/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dmno.dev/blog/dmno-nextjs-launch/</a><a href=\\"https://eslint.org/blog/2024/10/eslint-json-markdown-support/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eslint.org/blog/2024/10/eslint-json-markdown-support/</a><p data-notion-block-id=\\"7fe6080b-278f-4e18-9429-54bc711b22a1\\">\uccab\ubc88\uc9f8 \uae00\uc740 \ube14\ub8f8\ubc84\uadf8\uc5d0\uc11c CLI \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ub9cc\ub4e4\uae30 \uc804 \uace0\ub824\ud588\ub358 CLI \ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uacfc CLI \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ub9cc\ub4e0 \uc774\uc720\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#738ecb4b-eae9-4534-b05f-8bf0f4b8bb90\\">CodePush\uac00 \uc0ac\ub77c\uc9c0\uba74\uc11c</a> Microsoft\uc5d0\uc11c CodePush \uc11c\ubc84\ub97c \uc624\ud508\uc18c\uc2a4\ud654\ud55c \uac83\uc785\ub2c8\ub2e4. \uc138\ubc88\uc9f8 \uae00\uc740 \ud658\uacbd\ubcc0\uc218\ub97c \uad00\ub9ac\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 Next.js\ub97c \ud1b5\ud569\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc544\ub2c8\ub354\ub77c\ub3c4 <a href=\\"https://dotenvx.com/\\">dotenvx</a>\uac19\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \uc788\uc73c\ub2c8 \uc0b4\ud3b4\ubcf4\uace0 \uc801\uc6a9\ud574\ubcfc\ub9cc \ud558\uaca0\ub124\uc694. \ub124\ubc88\uc9f8 \uae00\uc740 ESLint\uac00 JSON\uacfc \ub9c8\ud06c\ub2e4\uc6b4\uc744 \uacf5\uc2dd\uc801\uc73c\ub85c \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"f868face-946a-46b0-bb28-8a06c82e2955\\"></p>"}')}}]);